fun groupAnagrams(words: Array<String>): List<List<String>> {
    val buckets = HashMap<String, MutableList<String>>()
    for (w in words) {
        val count = IntArray(26)
        for (c in w) count[c - 'a']++
        val key = count.joinToString(",")   // canonical form
        buckets.getOrPut(key) { mutableListOf() }.add(w)
    }
    return buckets.values.toList()
}

