fun maxArea(heights: IntArray): Int {
    var lo = 0
    var hi = heights.lastIndex
    var best = 0
    while (lo < hi) {
        val w = hi - lo
        val h = minOf(heights[lo], heights[hi])
        best = maxOf(best, w * h)
        if (heights[lo] < heights[hi]) lo++ else hi--
    }
    return best
}

