fun maxSumSubarray(arr: IntArray, k: Int): Int {
    require(k in 1..arr.size)
    var sum = arr.take(k).sum()
    var best = sum
    for (i in k until arr.size) {
        sum += arr[i] - arr[i - k]
        best = maxOf(best, sum)
    }
    return best
}

