fun subarraySum(nums: IntArray, k: Int): Int {
    val seen = HashMap<Int, Int>()   // prefix sum -> how many times it occurred
    seen[0] = 1                      // empty prefix
    var prefix = 0
    var count = 0
    for (x in nums) {
        prefix += x
        count += seen.getOrDefault(prefix - k, 0)
        seen.merge(prefix, 1, Int::plus)
    }
    return count
}

