fun shipWithinDays(weights: IntArray, days: Int): Int {
    fun canShip(cap: Int): Boolean {
        var day = 1
        var load = 0
        for (w in weights) {
            if (load + w > cap) { day++; load = 0 }
            load += w
        }
        return day <= days
    }
    var lo = weights.max()
    var hi = weights.sum()
    while (lo < hi) {
        val mid = (lo + hi) / 2
        if (canShip(mid)) hi = mid else lo = mid + 1
    }
    return lo
}

